mapper.insert:
INSERT INTO CLOUDWALK.RETRY_LOG (
    BUSINESS_TYPE, BUSINESS_ID, RETRY_COUNT, MAX_RETRY_COUNT,
    STATUS, ERROR_MESSAGE, NEXT_RETRY_TIME
) VALUES (
    #{businessType}, #{businessId}, #{retryCount}, #{maxRetryCount},
    #{status}, #{errorMessage}, #{nextRetryTime}
)

mapper.update:
UPDATE CLOUDWALK.RETRY_LOG
RETRY_COUNT = #{retryCount}, STATUS = #{status}, ERROR_MESSAGE = #{errorMessage}, NEXT_RETRY_TIME = #{nextRetryTime}, UPDATE_TIME = SYSTIMESTAMP
WHERE ID = #{id}

mapper.select:
SELECT 
FROM CLOUDWALK.RETRY_LOG
WHERE BUSINESS_TYPE = #{businessType}
AND BUSINESS_ID = #{businessId}

SELECT 
FROM CLOUDWALK.RETRY_LOG
WHERE STATUS = #{status}
AND NEXT_RETRY_TIME <= #{nextRetryTime}
AND RETRY_COUNT < MAX_RETRY_COUNT
ORDER BY NEXT_RETRY_TIME ASC

SELECT 
FROM CLOUDWALK.RETRY_LOG

    
        AND BUSINESS_TYPE = #{params.businessType}
    
    
        AND BUSINESS_ID = #{params.businessId}
    
    
        AND STATUS = #{params.status}
    
    
        AND CREATE_TIME >= #{params.startTime}
    
    
        AND CREATE_TIME <= #{params.endTime}
    

ORDER BY CREATE_TIME DESC

    OFFSET #{params.offset} ROWS FETCH NEXT #{params.limit} ROWS ONLY

SELECT COUNT(1)
FROM CLOUDWALK.RETRY_LOG

    
        AND BUSINESS_TYPE = #{params.businessType}
    
    
        AND BUSINESS_ID = #{params.businessId}
    
    
        AND STATUS = #{params.status}
    
    
        AND CREATE_TIME >= #{params.startTime}
    
    
        AND CREATE_TIME <= #{params.endTime}

mapper.delete:
DELETE FROM CLOUDWALK.RETRY_LOG
WHERE STATUS = 'SUCCESS'
AND CREATE_TIME < #{beforeTime}
